//! Filesystem layout shared by the `ps` daemon and the `ps-gui` settings app.
//!
//! The data files (`profiles/`, `layouts.json`) are generated by the Python
//! tooling.  They are resolved from the environment first (packaging), then
//! from an installed `~/.local/share/power_switcher/` next to the binary, and
//! finally from the source checkout, which is what `cargo run` uses.

use std::path::PathBuf;

/// Installed data directory: `<prefix>/share/power_switcher`, derived from
/// the binary location (`~/.local/bin/ps` → `~/.local/share/power_switcher`).
fn installed_share() -> Option<PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let bin_dir = exe.parent()?;
    let share = bin_dir.parent()?.join("share/power_switcher");
    share.is_dir().then_some(share)
}

/// N-gram profile directory (`<lang>_ngrams.json.gz` per layout).
///
/// Override with `PS_PROFILES_DIR`.
pub fn profiles_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("PS_PROFILES_DIR") {
        return PathBuf::from(dir);
    }
    if let Some(share) = installed_share() {
        let profiles = share.join("profiles");
        if profiles.is_dir() {
            return profiles;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../power_switcher/detection/profiles")
}

/// Exported keycode tables used by the detection engine.
///
/// Override with `PS_LAYOUTS_JSON`.
pub fn layouts_json() -> PathBuf {
    if let Ok(path) = std::env::var("PS_LAYOUTS_JSON") {
        return PathBuf::from(path);
    }
    if let Some(share) = installed_share() {
        let layouts = share.join("layouts.json");
        if layouts.is_file() {
            return layouts;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../ps-core/data/layouts.json")
}
